// Explicitly enabled, first-party funnel counts. No URL, referrer, prompt,
// credential, or persistent cross-visit identifier enters the payload. A page
// view may carry one coarse arrival class and, on the landing page after a
// click on a published Wiki's "Generated by CodeNib" link, that Wiki's public
// repository name.
const events = new Set([
  "page_view", "example_view", "example_source_open", "example_github_open",
  "example_wiki_open", "example_share", "repository_submit",
  "generation_form_view", "generation_start", "first_chapter_read", "agent_setup_open",
  "guard_case_view", "install_command_copy",
]);
const SEARCH_HOSTS = /(^|\.)(google\.[a-z.]{2,7}|bing\.com|duckduckgo\.com|search\.yahoo\.com|yandex\.[a-z]{2,3}|baidu\.com|ecosia\.org|search\.brave\.com|kagi\.com|startpage\.com|sogou\.com|naver\.com)$/;
const SOCIAL_HOSTS = /(^|\.)(news\.ycombinator\.com|reddit\.com|x\.com|t\.co|twitter\.com|linkedin\.com|lnkd\.in|facebook\.com|bsky\.app|mastodon\.social|discord\.com|weibo\.com|zhihu\.com|v2ex\.com|lobste\.rs)$/;
let send;

// `name` or `owner/name`, as GitHub spells repositories; never `.` or `..`.
export function isWikiRepository(value) {
  return typeof value === "string"
    && /^[A-Za-z0-9_.-]{1,100}(\/[A-Za-z0-9_.-]{1,100})?$/.test(value)
    && value.split("/").every(part => !/^\.+$/.test(part));
}

// Classify how this tab arrived. Only the class leaves the browser; the
// referrer itself is never sent. A Wiki link names its own public repository.
export function classifyArrival(search, referrer, ownHost) {
  const params = new URLSearchParams(search || "");
  const wiki = params.get("repo");
  if (params.get("ref") === "wiki" && isWikiRepository(wiki)) {
    return { arrival: "wiki_link", wiki };
  }
  let host = "";
  try { host = new URL(referrer).hostname.toLowerCase(); } catch { return {}; }
  if (!host || host === String(ownHost || "").toLowerCase()) return {};
  if (SEARCH_HOSTS.test(host)) return { arrival: "search" };
  if (SOCIAL_HOSTS.test(host)) return { arrival: "social" };
  if (host === "github.com" || host.endsWith(".github.com")) return { arrival: "github" };
  return { arrival: "other" };
}

// Drop the Wiki attribution parameters so a shared address stays clean.
export function withoutArrivalParameters(href) {
  let url;
  try { url = new URL(href); } catch { return href; }
  if (url.searchParams.get("ref") !== "wiki") return href;
  url.searchParams.delete("ref");
  url.searchParams.delete("repo");
  return url.href;
}

export function recordExperience(event) {
  if (events.has(event)) send?.(event);
}

export function installExperienceEvents(endpoint, surface, arrival = {}) {
  if (send || navigator.doNotTrack === "1" || navigator.globalPrivacyControl || !["landing", "wiki"].includes(surface)) return;
  let url;
  try { url = new URL(endpoint, location.href); } catch { return; }
  if (url.origin !== location.origin || !["http:", "https:"].includes(url.protocol)) return;
  if (typeof globalThis.crypto?.randomUUID !== "function") return;
  let visit = crypto.randomUUID().replaceAll("-", "");
  let seen = new Set();
  try {
    const prior = JSON.parse(sessionStorage.getItem("codenib-experience") || "null");
    if (/^[a-f0-9]{32}$/.test(prior?.visit)) {
      visit = prior.visit;
      seen = new Set((prior.events || []).filter(item => events.has(item)));
    }
  } catch { /* Storage restrictions do not affect the product. */ }
  // Only the landing page names the Wiki that sent the visit.
  const pageView = {};
  if (arrival.arrival === "wiki_link") {
    if (surface === "landing" && isWikiRepository(arrival.wiki)) {
      Object.assign(pageView, { arrival: "wiki_link", wiki: arrival.wiki });
    }
  } else if (["search", "social", "github", "other"].includes(arrival.arrival)) {
    pageView.arrival = arrival.arrival;
  }
  send = (event) => {
    if (seen.has(event)) return;
    seen.add(event);
    try { sessionStorage.setItem("codenib-experience", JSON.stringify({ visit, events: [...seen] })); } catch {}
    const extra = event === "page_view" ? pageView : {};
    void fetch(url.href, {
      method: "POST", credentials: "omit", referrerPolicy: "no-referrer", keepalive: true,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ event, surface, visit, ...extra }),
    }).catch(() => {});
  };
  document.addEventListener("codenib:experience", (event) => recordExperience(event.detail?.event));
  recordExperience("page_view");
}
